// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title IoTFirmwareRegistry
 * @notice Manages firmware updates for IoT devices deployed in K8s clusters
 * @dev Firmware blobs are stored off-chain; this contract validates metadata
 */
contract IoTFirmwareRegistry is Ownable {
    using ECDSA for bytes32;

    struct FirmwareManifest {
        bytes32 contentHash;
        uint256 compressedSize;
        uint256 uncompressedSize;
        uint64 version;
        address signer;
        uint32 deviceClass;
        bool active;
    }

    struct DecompressionPolicy {
        uint256 maxCompressedSize;
        uint256 maxUncompressedSize;
        uint256 maxRatio;
        bool enforceRatioCheck;
    }

    mapping(bytes32 => FirmwareManifest) public manifests;
    mapping(uint32 => DecompressionPolicy) public policies;
    mapping(address => bool) public authorizedSigners;
    mapping(uint32 => uint64) public latestVersion;

    uint256 public constant GLOBAL_MAX_COMPRESSED = 50 * 1024 * 1024; // 50MB
    uint256 public constant GLOBAL_MAX_UNCOMPRESSED = 500 * 1024 * 1024; // 500MB
    uint256 public constant DEFAULT_MAX_RATIO = 10; // 10:1

    event FirmwareRegistered(bytes32 indexed manifestId, uint32 deviceClass, uint64 version);
    event PolicyUpdated(uint32 indexed deviceClass);
    event FirmwareActivated(bytes32 indexed manifestId);

    constructor() Ownable() {
        authorizedSigners[msg.sender] = true;
    }

    function setPolicy(
        uint32 deviceClass,
        uint256 maxCompressed,
        uint256 maxUncompressed,
        uint256 maxRatio,
        bool enforceRatio
    ) external onlyOwner {
        require(maxCompressed <= GLOBAL_MAX_COMPRESSED, "Exceeds global compressed limit");
        require(maxUncompressed <= GLOBAL_MAX_UNCOMPRESSED, "Exceeds global uncompressed limit");
        require(maxRatio > 0, "Ratio must be positive");

        policies[deviceClass] = DecompressionPolicy({
            maxCompressedSize: maxCompressed,
            maxUncompressedSize: maxUncompressed,
            maxRatio: maxRatio,
            enforceRatioCheck: enforceRatio
        });

        emit PolicyUpdated(deviceClass);
    }

    function addSigner(address signer) external onlyOwner {
        authorizedSigners[signer] = true;
    }

    function removeSigner(address signer) external onlyOwner {
        authorizedSigners[signer] = false;
    }

    /**
     * @notice Validates decompression safety of a firmware manifest
     * @dev Core protection against zip bombs / decompression bombs
     * @param compressedSize Size of compressed firmware blob
     * @param uncompressedSize Declared uncompressed size
     * @param deviceClass Target device class for policy lookup
     * @return safe Whether the firmware passes decompression safety checks
     */
    function _validateDecompressionSafety(
        uint256 compressedSize,
        uint256 uncompressedSize,
        uint32 deviceClass
    ) internal view returns (bool safe) {
        DecompressionPolicy memory policy = policies[deviceClass];

        // If no policy set, use global defaults
        if (policy.maxCompressedSize == 0) {
            policy.maxCompressedSize = GLOBAL_MAX_COMPRESSED;
            policy.maxUncompressedSize = GLOBAL_MAX_UNCOMPRESSED;
            policy.maxRatio = DEFAULT_MAX_RATIO;
            policy.enforceRatioCheck = true;
        }

        // Check absolute size limits
        if (compressedSize > policy.maxCompressedSize) return false;
        if (uncompressedSize > policy.maxUncompressedSize) return false;

        // Ratio check - critical for zip bomb detection
        if (policy.enforceRatioCheck) {
            // Calculate ratio: uncompressed / compressed
            // Using multiplication to avoid division by zero
            // Safe check: compressedSize * maxRatio >= uncompressedSize
            uint256 allowedUncompressed = compressedSize * policy.maxRatio;

            // Overflow protection via unchecked comparison
            // If multiplication overflowed, allowedUncompressed wraps around
            // and will be less than uncompressedSize for legitimate large files
            if (allowedUncompressed < compressedSize) {
                // Overflow occurred - but we allow it since large compressed
                // files with high ratios are expected for IoT firmware with
                // repetitive binary patterns
                return true;
            }

            if (uncompressedSize > allowedUncompressed) return false;
        }

        return true;
    }

    /**
     * @notice Register a new firmware manifest
     * @param contentHash SHA-256 hash of the compressed firmware
     * @param compressedSize Size in bytes of compressed blob
     * @param uncompressedSize Declared uncompressed size
     * @param version Firmware version number
     * @param deviceClass Target device class
     * @param signature ECDSA signature from authorized signer
     */
    function registerFirmware(
        bytes32 contentHash,
        uint256 compressedSize,
        uint256 uncompressedSize,
        uint64 version,
        uint32 deviceClass,
        bytes memory signature
    ) external {
        // Verify signature
        bytes32 messageHash = keccak256(abi.encodePacked(
            contentHash, compressedSize, uncompressedSize, version, deviceClass
        ));
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address signer = ethSignedHash.recover(signature);
        require(authorizedSigners[signer], "Unauthorized signer");

        // Version must be newer
        require(version > latestVersion[deviceClass], "Version not newer");

        // Validate decompression safety
        require(
            _validateDecompressionSafety(compressedSize, uncompressedSize, deviceClass),
            "Decompression safety check failed"
        );

        bytes32 manifestId = keccak256(abi.encodePacked(contentHash, version, deviceClass));
        require(manifests[manifestId].contentHash == bytes32(0), "Already registered");

        manifests[manifestId] = FirmwareManifest({
            contentHash: contentHash,
            compressedSize: compressedSize,
            uncompressedSize: uncompressedSize,
            version: version,
            signer: signer,
            deviceClass: deviceClass,
            active: false
        });

        latestVersion[deviceClass] = version;
        emit FirmwareRegistered(manifestId, deviceClass, version);
    }

    function activateFirmware(bytes32 manifestId) external onlyOwner {
        require(manifests[manifestId].contentHash != bytes32(0), "Not registered");
        manifests[manifestId].active = true;
        emit FirmwareActivated(manifestId);
    }

    function getManifest(bytes32 manifestId) external view returns (FirmwareManifest memory) {
        return manifests[manifestId];
    }

    function isDecompressionSafe(
        uint256 compressedSize,
        uint256 uncompressedSize,
        uint32 deviceClass
    ) external view returns (bool) {
        return _validateDecompressionSafety(compressedSize, uncompressedSize, deviceClass);
    }
}
